mapper.select:
SELECT i.*,d.MONITOR_ENV,d.MONITOR_GROUP,d.DOCKER_SUMMARY,d.IS_ONLINE,d.ID AS dockerId FROM MONITOR_DOCKER_IMAGE i LEFT JOIN MONITOR_DOCKER d ON i.SERVER_IP = d.SERVER_IP
AND i.SERVER_IP LIKE CONCAT('%', #{params.serverIp}, '%')
AND i.IMAGE_REPOSITORY LIKE CONCAT('%', #{params.imageRepository}, '%')
AND d.MONITOR_ENV = #{params.monitorEnv}
AND d.MONITOR_GROUP = #{params.monitorGroup}

SELECT i.*,d.MONITOR_ENV,d.MONITOR_GROUP,d.DOCKER_SUMMARY,d.IS_ONLINE
FROM MONITOR_DOCKER_IMAGE i
LEFT JOIN MONITOR_DOCKER d ON i.SERVER_IP = d.SERVER_IP


        AND i.SERVER_IP = #{serverIp}


        AND i.IMAGE_ID = #{imageId}
